/// <summary>
/// Loads the local coder history records asynchronously.
/// </summary>
/// <returns>A task representing the asynchronous operation.</returns>
private async Task LoadAsync()
{
    isBusy = true;

    try
    {
        records = await HistoryService.GetAllAsync();

        if (selectedRecord is not null)
        {
            selectedRecord = records.FirstOrDefault(record => record.Id.Equals(selectedRecord.Id, StringComparison.OrdinalIgnoreCase));
        }
    }
    catch (Exception exception)
    {
        NotificationService.Notify(NotificationSeverity.Error, "History load failed", exception.Message);
    }
    finally
    {
        isBusy = false;
    }
}
```

### Notes
- Ensure that the `NotificationService` handles exceptions gracefully and provides meaningful error messages.
